"""Metric Based Phasing — Shiny for Python app.

Converted from the original Streamlit app. Analyzes Garmin .FIT files for
aerobic decoupling, efficiency factor (EF), durability metrics, and training
prescriptions.

UX/UI design follows the "Comprehensive Architecture and Design Strategy for
High-Performance Sports Analytics Applications in Shiny for Python" document:
  - Inverted Pyramid layout (KPIs → Trends → Deep Dive)
  - Semantic color palette (HR=Red, Power=Gold, Speed=Teal)
  - Dark mode CSS refinements (card depth, typography)
  - Progressive disclosure (accordions for advanced metrics)
  - Full-screen chart cards
  - RAG status colors (colorblind-safe)
  - Font Awesome icons on value boxes
"""

import asyncio
import hashlib
import inspect
import io
import json
import os
import re
import zipfile
from dataclasses import replace as dc_replace
import numpy as np
import pandas as pd
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

from shiny import App, Inputs, Outputs, Session, reactive, render, req, ui
from shiny.types import FileInfo
import shinyswatch
from htmltools import HTML, Tag, TagList, css, div, span, h3, h4, p, tags
import faicons as fa

# Local modules
from utils import (
    HISTORY_COLUMNS, PROFILE_META_START_TIME_ISO,
    sanitize_slug, history_path, format_duration,
    pace_str_from_speed_mps,
    _fmt_thr_pct, status_color_for,
    downsample_for_plot,
)
from terrain import (
    TERRAIN_THRESHOLDS, BIKE_TERRAIN_THRESHOLDS,
    thresholds_for_session, ergometer_thresholds_by_duration,
    TerrainInfo, add_ngp_speed, compute_terrain, ensure_elapsed_sec,
    terrain_decoupling_zone,
    compute_cardiac_cost_metrics_1hz, compute_segment_ef_stability,
    compute_power_decay_after_kj,
)
from fit_parser import (
    parse_fit_bytes, infer_mode, infer_erg_subtype,
    get_activity_weather_summary, extract_temp_bounds_from_weather_summary,
    choose_output_metric, combine_fit_workouts,
)
from history import (
    load_history, save_history,
    _history_upsert_row, load_history_cached,
    clear_history_cache,
)

# Import analysis module (eager import for Shinylive/Pyodide compatibility)
import analysis as _analysis_mod
def _get_analysis():
    return _analysis_mod

# Detect Shinylive / Pyodide (browser-based, no server-side network)
import sys
_IS_PYODIDE = sys.platform == "emscripten" or "pyodide" in sys.modules

# ---------------------------------------------------------------------------
# _maybe_await: wrapper for dual sync/async support
# ---------------------------------------------------------------------------
async def _maybe_await(result):
    """If result is awaitable (coroutine), await it; otherwise return as-is."""
    if inspect.isawaitable(result):
        return await result
    return result

# ---------------------------------------------------------------------------
# Proxy URL for Pyodide remote modules
# ---------------------------------------------------------------------------
_proxy_url: str = ""  # set by proxy UI in server()

# Eager-import remote sync modules so Shinylive registers them on the
# virtual filesystem (lazy imports inside functions fail in Pyodide).
_remote_garmin_mod = None
_remote_whoop_mod = None
try:
    import remote_garmin_sync as _remote_garmin_mod
except ImportError:
    pass
try:
    import remote_whoop_sync as _remote_whoop_mod
except ImportError:
    pass

# Garmin Connect sync (optional — server-side or remote via proxy)
_garmin_sync_mod = None
def _get_garmin_sync():
    global _garmin_sync_mod
    if _IS_PYODIDE:
        # In Pyodide, use remote module if proxy is configured
        if _proxy_url and _remote_garmin_mod is not None:
            _remote_garmin_mod.set_proxy_url(_proxy_url)
            return _remote_garmin_mod
        return None  # no proxy configured
    if _garmin_sync_mod is None:
        try:
            import garmin_sync
            _garmin_sync_mod = garmin_sync
        except ImportError:
            _garmin_sync_mod = False  # sentinel: not available
    return _garmin_sync_mod if _garmin_sync_mod is not False else None

# Whoop sync (optional — server-side or remote via proxy)
_whoop_sync_mod = None
def _get_whoop_sync():
    global _whoop_sync_mod
    if _IS_PYODIDE:
        # In Pyodide, use remote module if proxy is configured
        if _proxy_url and _remote_whoop_mod is not None:
            _remote_whoop_mod.set_proxy_url(_proxy_url)
            return _remote_whoop_mod
        return None  # no proxy configured
    if _whoop_sync_mod is None:
        try:
            import whoop_sync
            _whoop_sync_mod = whoop_sync
        except ImportError:
            _whoop_sync_mod = False
    return _whoop_sync_mod if _whoop_sync_mod is not False else None

# App base directory (where CSV history files live)
APP_DIR = Path(__file__).resolve().parent

# Pre-encoded images as base64 data URIs (Shinylive bundles .py files only)
from _images import IMG_MBP_INTRO, IMG_GARMIN_HELP, IMG_AD_INFOGRAPHIC, IMG_LAP_PRESS, IMG_TERRAIN

# Build metadata (auto-generated by CI, defaults for local dev)
try:
    from _build_info import IS_BETA, BUILD_TIMESTAMP
except ImportError:
    IS_BETA = False
    BUILD_TIMESTAMP = ""

# ---------------------------------------------------------------------------
# Plotly lazy loader
# ---------------------------------------------------------------------------
_plotly_go_cache = None
def _get_plotly_go():
    global _plotly_go_cache
    if _plotly_go_cache is None:
        import plotly.graph_objects as go
        _plotly_go_cache = go
    return _plotly_go_cache


# ===================================================================
# Whoop API key → history column mapping (shared by Analyze + Compare)
# ===================================================================
_WHOOP_COL_MAP = {
    "recovery_score": "whoop_score", "hrv_rmssd_milli": "whoop_hrv_ms",
    "resting_heart_rate": "whoop_resting_hr", "strain": "whoop_strain",
    "sleep_perf": "whoop_sleep_perf", "sleep_efficiency": "whoop_sleep_efficiency",
    "sleep_hours": "whoop_sleep_hours", "rem_min": "whoop_rem_min",
    "sws_min": "whoop_sws_min", "light_min": "whoop_light_min",
    "awake_min": "whoop_awake_min", "spo2": "whoop_spo2",
    "skin_temp": "whoop_skin_temp_c", "respiratory_rate": "whoop_resp_rate",
    "calories_kj": "whoop_calories_kj",
}

# ===================================================================
# Semantic Color Palette (from UX/UI doc Section 4.3)
# ===================================================================
# These are defined as Python constants and also injected as CSS variables.
COLOR_POWER = "#FFD700"       # Gold — energy/wattage
COLOR_HR = "#FF4136"          # Red — cardiac exertion
COLOR_CADENCE = "#2ECC40"     # Green — rhythm/flow
COLOR_SPEED = "#39CCCC"       # Teal — distinct from physio metrics
COLOR_ELEVATION = "#AAAAAA"   # Grey — earth-bound constraint
COLOR_EF = "#0074D9"          # Blue — efficiency
COLOR_ELITE = "#00FFFF"       # Cyan — colorblind-safe "good" (RAG)
COLOR_ADAPTING = "#FF851B"     # Orange — colorblind-safe "caution" (RAG)
COLOR_NEEDS_WORK = "#FF4136"  # Red — needs improvement


# ===================================================================
# Custom CSS (from UX/UI doc Sections 4.1, 4.2, 10.1)
# ===================================================================
CUSTOM_CSS = """
<style>
:root {
    --color-power: #FFD700;
    --color-hr: #FF4136;
    --color-cadence: #2ECC40;
    --color-speed: #39CCCC;
    --color-elevation: #AAAAAA;
    --color-ef: #0074D9;
    --color-elite: #00FFFF;
    --color-adapting: #FF851B;
    --color-needs-work: #FF4136;
    --bg-page: #101010;
    --bg-card: #1e1e1e;
    --bg-card-header: #252525;
}

/* Page background depth (Section 4.2) */
body, .bslib-page-fill {
    background-color: var(--bg-page) !important;
}

/* Card depth: slightly lighter than page to create depth without borders (Section 4.2) */
.card {
    background-color: var(--bg-card) !important;
    border: 1px solid rgba(255,255,255,0.06) !important;
    border-radius: 12px !important;
}
.card-header {
    background-color: var(--bg-card-header) !important;
    border-bottom: 1px solid rgba(255,255,255,0.06) !important;
    font-weight: 700 !important;
    letter-spacing: 0.02em;
}

/* Value box styling (Section 10.1) */
.bslib-value-box .value-box-title {
    text-transform: uppercase !important;
    font-size: 0.7rem !important;
    letter-spacing: 0.08em !important;
    opacity: 0.85;
}
.bslib-value-box .value-box-value {
    font-size: 1.6rem !important;
    font-weight: 800 !important;
    font-family: 'Roboto Mono', 'JetBrains Mono', monospace !important;
}
/* Value box showcase icon area — keep icons proportional, not smushed */
.bslib-value-box .value-box-showcase {
    min-width: 56px !important;
    max-width: 56px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    padding: 10px !important;
}
.bslib-value-box .value-box-showcase svg {
    width: 32px !important;
    height: 32px !important;
    flex-shrink: 0 !important;
}

/* Data table monospace (Section 4.2) */
.dataTable td, .dataTable th {
    font-family: 'Roboto Mono', 'JetBrains Mono', monospace !important;
    font-size: 0.82rem !important;
}

/* Accordion styling for progressive disclosure */
.accordion-button {
    background-color: var(--bg-card) !important;
    color: rgba(255,255,255,0.9) !important;
    font-weight: 600 !important;
}
.accordion-button:not(.collapsed) {
    background-color: var(--bg-card-header) !important;
}
.accordion-body {
    background-color: var(--bg-card) !important;
}

/* Sidebar refinement */
.bslib-sidebar-layout > .sidebar {
    background-color: #151515 !important;
    border-right: 1px solid rgba(255,255,255,0.06) !important;
}

/* Navbar — glassmorphism (Section 3.1.1) */
.navbar {
    background: rgba(10, 10, 10, 0.55) !important;
    -webkit-backdrop-filter: blur(16px) saturate(1.4) !important;
    backdrop-filter: blur(16px) saturate(1.4) !important;
    border-bottom: 1px solid rgba(255,255,255,0.10) !important;
    position: sticky !important;
    top: 0 !important;
    z-index: 1030 !important;
    box-shadow: 0 2px 16px rgba(0,0,0,0.35);
}

/* Status badge pill styling */
.status-badge {
    display: inline-block;
    padding: 6px 14px;
    border-radius: 999px;
    font-weight: 800;
    font-size: 13px;
    color: #fff;
}

/* Smooth transitions */
.card, .bslib-value-box, .accordion {
    transition: box-shadow 0.2s ease;
}
.card:hover {
    box-shadow: 0 2px 12px rgba(0,0,0,0.4);
}

/* Clickable images — zoom cursor */
.zoomable-img {
    cursor: zoom-in;
    transition: opacity 0.15s ease;
}
.zoomable-img:hover {
    opacity: 0.85;
}

/* Lightbox overlay */
.mbp-lightbox {
    display: none;
    position: fixed;
    top: 0; left: 0; width: 100vw; height: 100vh;
    background: rgba(0,0,0,0.92);
    z-index: 99999;
    justify-content: center;
    align-items: center;
}
.mbp-lightbox.active {
    display: flex;
}
.mbp-lightbox img {
    max-width: 92vw;
    max-height: 90vh;
    border-radius: 8px;
    box-shadow: 0 4px 40px rgba(0,0,0,0.8);
}
.mbp-lightbox-close {
    position: absolute;
    top: 18px; right: 24px;
    font-size: 36px;
    color: #fff;
    cursor: pointer;
    font-weight: 700;
    line-height: 1;
    z-index: 100000;
    background: rgba(0,0,0,0.5);
    border-radius: 50%;
    width: 48px; height: 48px;
    display: flex; align-items: center; justify-content: center;
}
.mbp-lightbox-close:hover {
    background: rgba(255,255,255,0.15);
}

/* Ensure modals appear above full-screen cards */
.modal-backdrop {
    z-index: 1060 !important;
}
.modal {
    z-index: 1070 !important;
}
.modal-dialog {
    z-index: 1080 !important;
}

/* Loading spinner */
@keyframes mbp-spin { to { transform: rotate(360deg); } }
.mbp-spinner {
    display: inline-block; width: 16px; height: 16px;
    border: 2px solid rgba(255,255,255,0.3); border-top-color: #00FFFF;
    border-radius: 50%; animation: mbp-spin 0.7s linear infinite;
    vertical-align: middle; margin-right: 6px;
}
</style>

<!-- Lightbox container + JS -->
<div class="mbp-lightbox" id="mbpLightbox" onclick="this.classList.remove('active')">
    <span class="mbp-lightbox-close" onclick="document.getElementById('mbpLightbox').classList.remove('active')">&times;</span>
    <img id="mbpLightboxImg" src="" alt="Zoomed image" onclick="event.stopPropagation()">
</div>
<script>
function mbpZoom(el){
    var lb=document.getElementById('mbpLightbox');
    document.getElementById('mbpLightboxImg').src=el.src;
    lb.classList.add('active');
}
function mbpGetSelectedISOs(){
    var cbs=document.querySelectorAll('.mbp-del-cb:checked');
    var isos=[]; cbs.forEach(function(cb){isos.push(cb.dataset.iso);});
    return JSON.stringify({isos:isos,ts:Date.now()});
}
function mbpSaveToStorage(slug,csvText){
    try{localStorage.setItem('mbp_csv_'+slug,csvText);}catch(e){}
}
function mbpSetLastProfile(slug){
    try{localStorage.setItem('mbp_last_profile',slug);}catch(e){}
}
function mbpGetLastProfile(){
    try{return localStorage.getItem('mbp_last_profile')||'';}catch(e){return '';}
}
function mbpRemoveFromStorage(slug){
    try{localStorage.removeItem('mbp_csv_'+slug);}catch(e){}
}
function mbpGetAllStorageKeys(){
    var keys=[];
    try{for(var i=0;i<localStorage.length;i++){
        var k=localStorage.key(i);
        if(k&&k.startsWith('mbp_csv_'))keys.push(k.substring(8));
    }}catch(e){}
    return JSON.stringify(keys);
}
function mbpGetStorageCsv(slug){
    try{return localStorage.getItem('mbp_csv_'+slug)||'';}catch(e){return '';}
}
// Register eval_js handler early so send_custom_message works immediately
(function _regEvalJs(){
    function _tryReg(){
        if(typeof Shiny!=='undefined'&&Shiny.addCustomMessageHandler){
            if(!window._mbpEvalJs){
                Shiny.addCustomMessageHandler('eval_js',function(m){eval(m);});
                window._mbpEvalJs=true;
            }
        } else {
            setTimeout(_tryReg, 100);
        }
    }
    if(document.readyState==='loading'){
        document.addEventListener('DOMContentLoaded', _tryReg);
    } else {
        _tryReg();
    }
})();
function mbpSortTable(th){
    var table=th.closest('table'), tbody=table.tBodies[0];
    var idx=Array.from(th.parentNode.children).indexOf(th);
    var rows=Array.from(tbody.rows);
    var asc=th.dataset.sortDir!=='asc'; th.dataset.sortDir=asc?'asc':'desc';
    rows.sort(function(a,b){
        var at=a.cells[idx].textContent.trim(), bt=b.cells[idx].textContent.trim();
        var an=parseFloat(at.replace(/[^0-9.\-]/g,'')), bn=parseFloat(bt.replace(/[^0-9.\-]/g,''));
        if(!isNaN(an)&&!isNaN(bn)) return asc?an-bn:bn-an;
        return asc?at.localeCompare(bt):bt.localeCompare(at);
    });
    rows.forEach(function(r){tbody.appendChild(r);});
}
</script>
"""


# ===================================================================
# Image helper (must be defined before UI tree that references it)
# ===================================================================

def _zoomable_img(src: str, alt: str = "", max_width: str = "800px") -> Tag:
    """Return an <img> that opens in a lightbox overlay when clicked."""
    return ui.tags.img(
        src=src,
        alt=alt,
        class_="zoomable-img",
        onclick="mbpZoom(this)",
        style=f"width: 100%; max-width: {max_width}; border-radius: 8px; margin-top: 8px;",
    )


# ===================================================================
# UI Definition
# ===================================================================

# Goal options for the Analyze page
GOAL_OPTIONS = {
    "default": "No specific goal (60 min default)",
    "10k": "10 km",
    "16k": "16 km (10 miler)",
    "half": "21.1 km (Half Marathon)",
    "32k": "32 km",
    "marathon": "42.2 km (Marathon)",
    "hyrox": "Hyrox",
    "custom_distance": "Custom distance (km)",
    "custom_time": "Custom time (minutes)",
}

GOAL_DISTANCES_KM = {
    "10k": 10.0,
    "16k": 16.0,
    "half": 21.1,
    "32k": 32.0,
    "marathon": 42.2,
}

# --- Analyze sidebar (pill tabset: Steps + Settings) ---
analyze_sidebar = ui.sidebar(
    ui.navset_pill(
        ui.nav_panel(
            "Steps",
            # Proxy server connection (visible only in Pyodide/Shinylive)
            *(
                [ui.card(
                    ui.card_header("🔗 Proxy Server"),
                    ui.p(
                        "Connect to your local proxy server to access Garmin & Whoop data.",
                        style="font-size: 11px; opacity: 0.7; margin-bottom: 6px;",
                    ),
                    ui.input_text("proxy_url", "Proxy URL", value="http://localhost:9876",
                                  placeholder="http://localhost:9876"),
                    ui.input_action_button("proxy_connect_btn", "Connect to Proxy",
                                           class_="btn-outline-info btn-sm"),
                    ui.output_ui("proxy_status_ui"),
                )]
                if _IS_PYODIDE else []
            ),
            # Step 1: Goal selection
            ui.card(
                ui.card_header("Step 1. Pick your event or goal distance"),
                ui.input_select(
                    "goal_choice", "Choose your goal:",
                    choices=GOAL_OPTIONS,
                    selected="default",
                ),
                ui.panel_conditional(
                    "input.goal_choice === 'custom_distance'",
                    ui.input_numeric("goal_custom_distance_km", "Custom distance (km)", value=10.0, min=1, max=500, step=0.1),
                ),
                ui.panel_conditional(
                    "input.goal_choice === 'custom_time'",
                    ui.input_numeric("goal_custom_time_min", "Custom time (minutes)", value=60.0, min=10, max=2000, step=5),
                ),
                ui.output_text("goal_summary_text"),
            ),
            # Step 2: Upload
            ui.card(
                ui.card_header("Step 2. Upload your .FIT file"),
                ui.input_file("fit_file", "Upload activity file (.FIT or .zip)", accept=[".fit", ".zip"], multiple=True),
                ui.output_ui("upload_status"),
                ui.accordion(
                    ui.accordion_panel(
                        "How to get .fit or .zip file from Garmin Connect app?",
                        _zoomable_img(IMG_GARMIN_HELP, "How to export FIT file from Garmin Connect"),
                        icon=fa.icon_svg("circle-question"),
                    ),
                    id="garmin_help_accordion",
                    open=False,
                ),
            ),
            # --- Or fetch from Garmin Connect ---
            ui.accordion(
                ui.accordion_panel(
                    "Or fetch from Garmin Connect",
                    ui.output_ui("garmin_connect_ui"),
                    icon=fa.icon_svg("cloud-arrow-down"),
                ),
                id="garmin_connect_accordion",
                open=False,
            ),
            # --- Or fetch from Whoop ---
            ui.accordion(
                ui.accordion_panel(
                    "Or fetch from Whoop",
                    ui.output_ui("whoop_connect_ui"),
                    icon=fa.icon_svg("heart-pulse"),
                ),
                id="whoop_connect_accordion",
                open=False,
            ),
            # Step 3: Warm-up / Exclusions
            ui.card(
                ui.card_header("Step 3. Warm-up / Exclusions"),
                ui.input_numeric("warmup_min", "Warm-up exclusion (minutes)", value=15, min=0, max=240, step=1),
                ui.input_numeric("end_exclude_min", "End exclusion (minutes)", value=0, min=0, max=120, step=1),
            ),
            # Step 4: History save
            ui.output_ui("history_save_section"),
        ),
        ui.nav_panel(
            "Settings",
            ui.h5("Power-based cleaning"),
            ui.input_numeric("ftp_w", "FTP (watts)", value=0, min=0, max=2000, step=5),
            ui.input_slider("stride_thr_pct", "Stride threshold (% of FTP)", min=1.05, max=1.60, value=1.25, step=0.01),
            ui.input_numeric("min_stride_confirm_sec", "Min stride confirmation (sec)", value=3, min=1, max=15, step=1),
            ui.input_numeric("recovery_buffer_sec", "Recovery buffer after strides (sec)", value=60, min=0, max=300, step=5),
            ui.input_select(
                "stride_mode", "Stride handling",
                choices=[
                    "Option A — stop analysis at first stride",
                    "Option B — remove strides + recovery; use all remaining segments",
                ],
            ),
            ui.hr(),
            ui.h5("Pause fallback"),
            ui.input_numeric("pause_power_w", "Paused if power ≤ (W)", value=5.0, min=0, max=100, step=1),
            ui.input_numeric("pause_speed_kph", "…and speed ≤ (km/h)", value=0.8, min=0, max=10, step=0.1),
            ui.hr(),
            ui.h5("Hydration"),
            ui.input_numeric("sweat_rate_lph", "Sweat rate (L/hour)", value=0.0, min=0, max=3, step=0.05),
        ),
        id="sidebar_tabs",
    ),
    open="desktop",
    width=320,
)

# --- Compare sidebar ---
compare_sidebar = ui.sidebar(
    ui.h4("Control Panel"),
    ui.div(
        ui.input_selectize("compare_profile", "Athlete Profile", choices=[], options={"create": True, "persist": True}),
        ui.tags.small("Type to Create or Select", style="display:block; margin-top:-10px; opacity:0.6; font-size:11px;"),
    ),
    # --- Delete profile ---
    ui.accordion(
        ui.accordion_panel(
            "Delete entire profile?",
            ui.p(
                "Delete this athlete profile (and all saved sessions) from the app. This cannot be undone.",
                style="font-size: 12px; opacity: 0.7; margin-bottom: 8px;",
            ),
            ui.input_action_button("delete_profile_btn", ui.TagList(fa.icon_svg("trash"), " Delete this profile"), class_="btn-danger btn-sm"),
            ui.output_ui("delete_profile_status"),
            icon=fa.icon_svg("trash-can"),
        ),
        id="delete_profile_accordion",
        open=False,
    ),
    # --- Rename profile ---
    ui.accordion(
        ui.accordion_panel(
            "Rename profile?",
            ui.p(
                "Rename the currently selected athlete profile.",
                style="font-size: 12px; opacity: 0.7; margin-bottom: 8px;",
            ),
            ui.input_text("rename_profile_input", "New profile name", placeholder="Enter new name"),
            ui.input_action_button("rename_profile_btn", ui.TagList(fa.icon_svg("pen"), " Rename"), class_="btn-warning btn-sm"),
            icon=fa.icon_svg("pen-to-square"),
        ),
        id="rename_profile_accordion",
        open=False,
    ),
    # --- Upload sessions ---
    ui.accordion(
        ui.accordion_panel(
            "Upload sessions?",
            ui.p(
                "Upload .fit / .zip files (one or many). Files are pre-scanned so you can supply missing power, distance, or RPE before saving.",
                style="font-size: 12px; opacity: 0.7; margin-bottom: 8px;",
            ),
            ui.input_file("compare_fit_upload", "Upload .FIT / .zip files", accept=[".fit", ".zip"], multiple=True),
            # --- Or fetch from Garmin Connect ---
            ui.output_ui("compare_garmin_ui"),
            # --- Or fetch from Whoop ---
            ui.output_ui("compare_whoop_ui"),
            ui.output_ui("compare_fit_prescan"),
            ui.input_action_button("compare_save_sessions", "Save uploaded sessions", class_="btn-primary btn-sm"),
            ui.output_ui("compare_save_status"),
            icon=fa.icon_svg("file-arrow-up"),
        ),
        id="upload_sessions_accordion",
        open=False,
    ),
    ui.hr(),
    ui.h5("Filters"),
    # --- Activity types (dropdown with switches) ---
    ui.accordion(
        ui.accordion_panel(
            "Activity Types",
            ui.output_ui("compare_activity_switches"),
            icon=fa.icon_svg("person-running"),
        ),
        id="activity_types_accordion",
        open=False,
    ),
    # --- Elevation profile (just below Activity Types) ---
