        def _add_mode_traces(fig, x_col, y_series, base_color, name_prefix, hover_fmt, y_valid_mask=None):
            """Add per-mode marker traces + a connecting line trace."""
            if y_valid_mask is None:
                y_valid_mask = y_series.notna()
            # Thin connecting line for overall trend (no markers)
            ok = y_valid_mask
            if ok.any():
                fig.add_trace(go.Scatter(
                    x=hist_sorted.loc[ok, x_col], y=y_series[ok],
                    mode="lines", name=name_prefix,
                    line=dict(color=base_color, width=1.5), opacity=0.5,
                    showlegend=False,
                ))
            # Per-mode marker traces
            for m in _unique_modes:
                info = _MODE_MARKER.get(m, {"symbol": "star", "label": m.title()})
                m_mask = ok & (_mode_col == m)
                if not m_mask.any():
                    continue
                fig.add_trace(go.Scatter(
                    x=hist_sorted.loc[m_mask, x_col],
                    y=y_series[m_mask],
                    mode="markers",
                    name=info["label"],
                    marker=dict(
                        symbol=info["symbol"],
                        size=9,
                        color=_MODE_COLOR_TINT.get(m, base_color),
                        line=dict(width=1, color="rgba(255,255,255,0.4)"),
                    ),
                    hovertemplate=f"{info['label']}: {hover_fmt}<extra></extra>",
                    legendgroup=m,
