    async def _open_edit_modal_for_idx(idx):
        """Open/replace the edit modal for the session at the given index."""
        isos = _pending_edit_isos()
        if not isos or idx < 0 or idx >= len(isos):
            return
        _edit_current_idx.set(idx)

        slug = input.compare_profile()
        if not slug:
            return
        hp = APP_DIR / f"ad_history_{slug}.csv"
        hist = load_history(hp)
        if hist.empty or "start_time_iso" not in hist.columns:
            return

        row_data = _get_row_data_for_iso(isos[idx], hist)
        if not row_data:
            ui.notification_show(f"Session {idx + 1} not found.", type="warning", duration=3)
            return

        form_html = _build_edit_form_html(row_data, idx, len(isos))

        # Remove existing modal first to prevent stacking
        ui.modal_remove()

        await asyncio.sleep(0.15)  # brief pause so DOM clears old modal

        ui.modal_show(
            ui.modal(
                ui.HTML(form_html),
                title="Edit Session",
                easy_close=True,
                size="l",
                footer=None,
            ),
        )

        await asyncio.sleep(0.1)  # ensure modal DOM is rendered before wiring JS
        await session.send_custom_message("eval_js", _EDIT_WIRE_JS)

