    @reactive.Effect
    @reactive.event(input._edit_nav)
    async def _edit_navigate():
        """Handle Prev/Next navigation in edit modal."""
        raw = input._edit_nav()
        if not raw:
            return
        try:
            data = json.loads(raw)
            direction = data.get("dir", "")
        except Exception:
            return
        idx = _edit_current_idx()
        total = len(_pending_edit_isos())
        if direction == "prev" and idx > 0:
            await _open_edit_modal_for_idx(idx - 1)
        elif direction == "next" and idx < total - 1:
            await _open_edit_modal_for_idx(idx + 1)

    @reactive.Effect
    @reactive.event(input._edit_save_data)
    async def _execute_edit_session():
        raw = input._edit_save_data()
        if not raw:
            return
        try:
            data = json.loads(raw)
            updates = data.get("updates", {})
        except Exception:
            updates = {}

        # Extract the ISO for this specific session
        iso_val = updates.pop("_iso", None)
        if not iso_val and _pending_edit_isos():
            idx = _edit_current_idx()
            isos = _pending_edit_isos()
            if 0 <= idx < len(isos):
                iso_val = isos[idx]

        slug = input.compare_profile()
        req(slug)
        hp = APP_DIR / f"ad_history_{slug}.csv"
        hist = load_history(hp)
        if hist.empty or "start_time_iso" not in hist.columns:
            return

        if not updates or not iso_val:
            ui.notification_show("No changes to save.", type="warning", duration=3)
            return

        # Apply updates to THIS session only
        mask = hist["start_time_iso"].astype(str) == str(iso_val)
        n_updated = int(mask.sum())
        for col, val in updates.items():
            if col in hist.columns:
                hist.loc[mask, col] = val

        if n_updated > 0:
            save_history(hist, hp)
            await _persist_to_browser(slug)
            clear_history_cache()
            history_trigger.set(history_trigger() + 1)

        # Advance to next session or close
        idx = _edit_current_idx()
        total = len(_pending_edit_isos())
        if idx < total - 1:
            ui.notification_show(f"\u270f\ufe0f Saved session {idx + 1} of {total}.", type="message", duration=2)
            await _open_edit_modal_for_idx(idx + 1)
        else:
            ui.modal_remove()
            ui.notification_show(
                f"\u270f\ufe0f Saved {total} session(s)." if total > 1 else "\u270f\ufe0f Session updated.",
                type="message", duration=4,
            )
            _pending_edit_isos.set([])

